struct Record<'a> {
    best: &'a str,
}

impl<'a> Record<'a> {
    fn offer(&mut self, title: &'a str) {
        if title < self.best {
            self.best = title;
        }
    }
}

fn main() {
    let list = String::from("Moby Emma Dune Ulysses Beloved");
    let mut rec = Record { best: "zzz" };
    for t in list.split(' ') {
        rec.offer(t);
        println!("{t} {}", rec.best);
    }
}

