    let shelf = vec![String::from("Emma")];
    let spare = String::from("(empty)");
    println!("{}", longer("Dune", "Beloved"));
    println!("{}", title_of("Dune: a novel", "Ana"));
    println!("{}", pick(1, "Emma", "Ulysses"));
    println!("{}", first_or(&shelf, &spare));
    println!("{}", first_or(&[], &spare));
}

