struct Excerpt<'a> {
    part: &'a str,
}

impl<'a> Excerpt<'a> {
    fn new(text: &'a str) -> Excerpt<'a> {
        let part = text.split('.').next().unwrap_or("");
        Excerpt { part }
    }

    fn words(&self) -> usize {
        self.part.split_whitespace().count()
    }

    fn announce(&self, msg: &str) -> &str {
        println!("Attention: {msg}");
        self.part
    }
}

fn main() {
    let story = String::from("The lamp was lit. Mabel read on.");
    let e = Excerpt::new(&story);
    println!("{} words", e.words());
    println!("{}", e.announce("story hour"));
}

